-- School identity, staff IDs, generated admission numbers, public CMS media and admin finance/program access.
create table if not exists public.school_number_sequences(sequence_key text not null,sequence_year integer not null,next_number integer not null default 1,primary key(sequence_key,sequence_year));
alter table public.profiles add column if not exists staff_id text;
alter table public.profiles add column if not exists employment_status text not null default 'active' check (employment_status in ('active','inactive','suspended','left'));
alter table public.profiles add column if not exists job_title text;
alter table public.profiles add column if not exists department text;
alter table public.profiles add column if not exists joined_on date;
create unique index if not exists profiles_staff_id_unique on public.profiles(staff_id) where staff_id is not null;
create or replace function public.next_school_number(p_key text,p_year integer) returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin insert into public.school_number_sequences(sequence_key,sequence_year,next_number) values(p_key,p_year,2) on conflict(sequence_key,sequence_year) do update set next_number=school_number_sequences.next_number+1 returning next_number-1 into n; return n; end $$;
grant execute on function public.next_school_number(text,integer) to authenticated;
create or replace function public.generate_staff_id(p_role public.user_role,p_year integer) returns text language plpgsql security definer set search_path=public as $$ declare n integer; begin if p_role in ('teacher','principal','admin','super_admin','finance','admissions','security') then n:=public.next_school_number('staff',p_year); return 'AMQM/STF/'||p_year::text||'/'||lpad(n::text,3,'0'); end if; return null; end $$;
create or replace function public.assign_staff_id() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.staff_id is null or btrim(new.staff_id)='' then new.staff_id:=public.generate_staff_id(new.role,extract(year from coalesce(new.joined_on,current_date))::integer); end if; return new; end $$;
drop trigger if exists profiles_assign_staff_id on public.profiles;
create trigger profiles_assign_staff_id before insert on public.profiles for each row execute function public.assign_staff_id();
insert into public.school_number_sequences(sequence_key,sequence_year,next_number) select 'staff',y,coalesce(max(n),0)+1 from (select extract(year from coalesce(joined_on,created_at::date))::integer y,nullif(regexp_replace(staff_id,'^AMQM/STF/[0-9]{4}/',''),'')::integer n from public.profiles where staff_id is not null) x group by y on conflict(sequence_key,sequence_year) do update set next_number=greatest(school_number_sequences.next_number,excluded.next_number);
update public.profiles p set staff_id=public.generate_staff_id(p.role,extract(year from coalesce(p.joined_on,p.created_at::date))::integer) where p.staff_id is null and p.role in ('teacher','principal','admin','super_admin','finance','admissions','security');
create or replace function public.generate_student_admission_no(p_year integer) returns text language plpgsql security definer set search_path=public as $$ begin return 'AMQM/Stu/'||p_year::text||'/'||lpad(public.next_school_number('student',p_year)::text,3,'0'); end $$;
grant execute on function public.generate_student_admission_no(integer) to authenticated;
create or replace function public.assign_student_admission_no() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.admission_no is null or btrim(new.admission_no)='' or lower(btrim(new.admission_no)) in ('auto','generate') then new.admission_no:=public.generate_student_admission_no(extract(year from coalesce(new.admission_date,current_date))::integer); end if; return new; end $$;
drop trigger if exists students_assign_admission_no on public.students;
create trigger students_assign_admission_no before insert on public.students for each row execute function public.assign_student_admission_no();
insert into storage.buckets(id,name,public) values('school-public-media','school-public-media',true) on conflict(id) do update set public=true;
drop policy if exists "admins upload public school media" on storage.objects;
drop policy if exists "admins update public school media" on storage.objects;
drop policy if exists "admins delete public school media" on storage.objects;
drop policy if exists "public read school media" on storage.objects;
create policy "admins upload public school media" on storage.objects for insert to authenticated with check(bucket_id='school-public-media' and public.my_role() in ('super_admin','admin','principal'));
create policy "admins update public school media" on storage.objects for update to authenticated using(bucket_id='school-public-media' and public.my_role() in ('super_admin','admin','principal')) with check(bucket_id='school-public-media' and public.my_role() in ('super_admin','admin','principal'));
create policy "admins delete public school media" on storage.objects for delete to authenticated using(bucket_id='school-public-media' and public.my_role() in ('super_admin','admin','principal'));
create policy "public read school media" on storage.objects for select to anon,authenticated using(bucket_id='school-public-media');
drop policy if exists "public media only when marked public" on public.media_library;
drop policy if exists "public media published via team profiles" on public.media_library;
create policy "public media only when marked public" on public.media_library for select to anon,authenticated using(is_public=true or public.my_role() in ('super_admin','admin','principal'));
create policy "finance admins insert student fees" on public.student_fees for insert to authenticated with check(public.my_role() in ('super_admin','admin','principal','finance'));
create policy "finance admins update student fees" on public.student_fees for update to authenticated using(public.my_role() in ('super_admin','admin','principal','finance')) with check(public.my_role() in ('super_admin','admin','principal','finance'));
create policy "finance admins delete student fees" on public.student_fees for delete to authenticated using(public.my_role() in ('super_admin','admin','principal','finance'));
create policy "finance admins insert payments" on public.payments for insert to authenticated with check(public.my_role() in ('super_admin','admin','principal','finance'));
create policy "finance admins update payments" on public.payments for update to authenticated using(public.my_role() in ('super_admin','admin','principal','finance')) with check(public.my_role() in ('super_admin','admin','principal','finance'));
create policy "finance admins delete payments" on public.payments for delete to authenticated using(public.my_role() in ('super_admin','admin','principal','finance'));
drop policy if exists "admins insert homepage" on public.homepage_sections;
drop policy if exists "admins update homepage" on public.homepage_sections;
drop policy if exists "admins delete homepage" on public.homepage_sections;
create policy "admins insert homepage" on public.homepage_sections for insert to authenticated with check(public.my_role() in ('super_admin','admin','principal'));
create policy "admins update homepage" on public.homepage_sections for update to authenticated using(public.my_role() in ('super_admin','admin','principal')) with check(public.my_role() in ('super_admin','admin','principal'));
create policy "admins delete homepage" on public.homepage_sections for delete to authenticated using(public.my_role() in ('super_admin','admin','principal'));
drop policy if exists "admins insert settings" on public.site_settings;
drop policy if exists "admins update settings" on public.site_settings;
drop policy if exists "admins delete settings" on public.site_settings;
create policy "admins insert settings" on public.site_settings for insert to authenticated with check(public.my_role() in ('super_admin','admin','principal'));
create policy "admins update settings" on public.site_settings for update to authenticated using(public.my_role() in ('super_admin','admin','principal')) with check(public.my_role() in ('super_admin','admin','principal'));
create policy "admins delete settings" on public.site_settings for delete to authenticated using(public.my_role() in ('super_admin','admin','principal'));
insert into public.site_settings(key,value) values('school_name','{"value":"ALIYU AND MAIMUNA CENTER FOR QUR''ANIC MEMORIZATION"}'::jsonb),('short_name','{"value":"AMQM"}'::jsonb),('tagline','{"value":"Qur''anic memorization, education, character and excellence."}'::jsonb),('logo_url','{"value":""}'::jsonb),('favicon_url','{"value":""}'::jsonb),('contact','{"phone":"","email":"","address":"","website":""}'::jsonb),('social_links','{"facebook":"","instagram":"","youtube":"","whatsapp":"","tiktok":""}'::jsonb) on conflict(key) do update set value=excluded.value,updated_at=now();
update public.homepage_sections set title=case section_key when 'hero' then 'Welcome to Aliyu and Maimuna Center for Qur''anic Memorization' when 'features' then 'Why Choose AMQM?' when 'about' then 'About AMQM' when 'stats' then 'Our School at a Glance' when 'programme' then 'Our Programmes' when 'values' then 'Our Values' when 'campuses' then 'Our Learning Environment' when 'news' then 'Latest News & Announcements' when 'footer' then 'Aliyu and Maimuna Center for Qur''anic Memorization' else title end, content=case section_key when 'hero' then jsonb_build_object('eyebrow','Aliyu and Maimuna Center for Qur''anic Memorization','title','Qur''an memorization with knowledge, character and excellence','subtitle','A structured learning environment dedicated to helping students memorize the Qur''an while developing strong character, discipline and Islamic knowledge.','hero_image','','hero_video','','quote','','quote_source','','primary_cta','Apply for Admission','primary_href','/admissions','secondary_cta','Learn More','secondary_href','/about') when 'features' then jsonb_build_object('items',jsonb_build_array(jsonb_build_object('title','Qur''an Memorization','text','Structured memorization with continuous progress tracking'),jsonb_build_object('title','Day & Boarding','text','Flexible learning arrangements for students and families'),jsonb_build_object('title','Qualified Teachers','text','Dedicated teachers supporting memorization and character development'),jsonb_build_object('title','Continuous Assessment','text','Regular evaluation, feedback and academic support'),jsonb_build_object('title','Student Development','text','Balanced Qur''anic, academic and character development'),jsonb_build_object('title','Safe Learning Environment','text','A supportive environment designed for focused learning'))) when 'about' then jsonb_build_object('title','About Our Center','text','Aliyu and Maimuna Center for Qur''anic Memorization is committed to quality Qur''anic memorization, Islamic education and character development.','image','','cta','More About Us','cta_href','/about') when 'programme' then jsonb_build_object('title','Qur''an Memorization Programme','text','Our programme can be configured by administrators for years, terms, assessments and learning targets.','items',jsonb_build_array()) else content end where section_key in ('hero','features','about','programme','stats','values','campuses','news','footer');
update public.pages set title=replace(replace(title,'Al Huda','Aliyu and Maimuna Center for Qur''anic Memorization'),'AL HUDA','Aliyu and Maimuna Center for Qur''anic Memorization'), content=replace(replace(content::text,'Al Huda','Aliyu and Maimuna Center for Qur''anic Memorization'),'AL HUDA','Aliyu and Maimuna Center for Qur''anic Memorization')::jsonb;
update public.site_settings set value=replace(replace(value::text,'AL HUDA QURAN MEMORIZATION SCHOOL','ALIYU AND MAIMUNA CENTER FOR QUR''ANIC MEMORIZATION'),'Al Huda','Aliyu and Maimuna Center for Qur''anic Memorization')::jsonb;
create policy "admins insert programs principal" on public.programs for insert to authenticated with check(public.my_role() in ('super_admin','admin','principal'));
create policy "admins update programs principal" on public.programs for update to authenticated using(public.my_role() in ('super_admin','admin','principal')) with check(public.my_role() in ('super_admin','admin','principal'));
create policy "admins delete programs principal" on public.programs for delete to authenticated using(public.my_role() in ('super_admin','admin','principal'));
